{
 "quarter": "Q4 FY26",
 "callDate": "2026-05-12",
 "guidance": [
  {
   "metric": "volume",
   "statement": "Expect a high-double-digit growth quarter-on-quarter in smartphones volume with selling prices up 12% to 15%.",
   "quote": "we expect a high-double-digit growth quarter-on-quarter in the smartphones volume along with growth in selling prices by 12% to 15%.",
   "page": 4,
   "horizon": "next quarter",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "IT hardware revenue is expected to cross INR4,000 crores in the current fiscal.",
   "quote": "we feel that our revenue in this fiscal is going to be more than INR4,000 crores.",
   "page": 9,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Telecom network revenue is targeted at INR7,500 crores to INR8,000 crores in FY27.",
   "quote": "We are targeting almost INR7,500 crores, INR8,000 crores in '26, '27.",
   "page": 9,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Lighting revenues are expected to grow almost 2x in the current fiscal.",
   "quote": "we expect the revenues to grow almost to 2x in the current fiscal.",
   "page": 6,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "volume",
   "statement": "Camera module capacity is expanding from 70 million units to 180-190 million units annually.",
   "quote": "expanding the capacities of camera module and a subsidiary Q Tech... from 70 million units annually to around 180 million units to 190 million units annually over the next 15 to 18 months",
   "page": 4,
   "horizon": "15 to 18 months",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Camera module revenue target is INR2,500 crores in the current fiscal.",
   "quote": "We are targeting a revenue of almost INR2,500 crores in that business.",
   "page": 9,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Company targets overall revenue growth of 15% to 17% without Vivo numbers.",
   "quote": "We feel that without the Vivo also, the company will keep growing at almost 15% to 17%.",
   "page": 15,
   "horizon": "FY27",
   "quantitative": true
  }
 ],
 "delivered": [
  {
   "metric": "revenue",
   "statement": "Q4 FY26 revenues were INR10,520 crores and FY26 revenues reached INR48,893 crores, up 26%.",
   "quote": null,
   "page": 3
  },
  {
   "metric": "profit",
   "statement": "Q4 FY26 EBITDA was INR418 crores and PAT was INR192 crores (excluding exceptional items).",
   "quote": null,
   "page": 3
  },
  {
   "metric": "revenue",
   "statement": "FY26 mobile and other EMS revenue was INR9,485 crores with operating profit of INR337 crores.",
   "quote": null,
